package validation

import (
	"fyne.io/fyne/v2"
)

// NewAllStrings creates a validator that checks if all strings in a slice pass a given validator.
// The returned validator accepts a string slice and validates each element.
// If any element fails validation, the first error encountered is returned.
//
// Since: 2.2
func NewAllStrings(itemValidator fyne.StringValidator) func([]string) error {
	if itemValidator == nil {
		return func([]string) error {
			return nil
		}
	}

	return func(values []string) error {
		for _, value := range values {
			if err := itemValidator(value); err != nil {
				return err
			}
		}
		return nil
	}
}
